const a = rng.pick([1, 1, -1, -1, 2, -2]);
const gap = Math.abs(a) === 2 ? 2 : rng.pick([2, 4]);
const vx = rng.int(-4 + gap / 2, 4 - gap / 2);
const r1 = vx - gap / 2, r2 = vx + gap / 2;
const vy = -a * (gap / 2) * (gap / 2);
// y = a x^2 + b x + c
const b = -a * (r1 + r2), c = a * r1 * r2;
const term = (k, x, first) => {
  if (k === 0) return "";
  const sign = k < 0 ? "-" : first ? "" : "+";
  const mag = Math.abs(k) === 1 && x ? "" : String(Math.abs(k));
  return `${sign} ${mag}${x}`.trim();
};
const tex = [term(a, "x^2", true), term(b, "x", false), term(c, "", false)].filter(Boolean).join(" ").replace(/\s+/g, " ").replace(/^- /, "-");
const factored = `${a === 1 ? "" : a === -1 ? "-" : a}(x ${r1 < 0 ? "+" : "-"} ${Math.abs(r1)})(x ${r2 < 0 ? "+" : "-"} ${Math.abs(r2)})`.replace(/\(x - 0\)/g, "x").replace(/\(x \+ 0\)/g, "x");
return {
  prompt: `Mark both roots and the vertex of $y = ${tex}$.`,
  points: [[r1, 0], [r2, 0], [vx, vy]],
  labels: ["root", "root", "vertex"],
  curve: `${a}*(x-(${r1}))*(x-(${r2}))`,
  explanation: `Factor it: $y = ${factored}$, so the roots are $x = ${r1}$ and $x = ${r2}$. The vertex sits halfway between them, at $x = \\frac{${r1} + ${r2 < 0 ? `(${r2})` : r2}}{2} = ${vx}$, and $y(${vx}) = ${vy}$. It's a ${a > 0 ? "minimum, since the parabola opens upward" : "maximum, since the parabola opens downward"} ($a = ${a}$).`,
};

const slopes = [-2, -1, 1, 2];
for (;;) {
  const px = rng.int(-3, 3), py = rng.pick([-3, -2, -1, 1, 2, 3]);
  const [m1, m2] = rng.shuffle(slopes).slice(0, 2);
  if (m1 === m2) continue;
  const x1 = px - py / m1, x2 = px - py / m2;
  if (Math.abs(x1) > 4.5 || Math.abs(x2) > 4.5) continue;
  const b1 = py - m1 * px, b2 = py - m2 * px;
  const line = (m, b) => {
    const mx = m === 1 ? "x" : m === -1 ? "-x" : `${m}x`;
    return b === 0 ? mx : `${mx} ${b < 0 ? "-" : "+"} ${Math.abs(b)}`;
  };
  const fr = (v) => (Number.isInteger(v) ? String(v) : (v < 0 ? "-" : "") + `\\tfrac{${Math.abs(v * 2)}}{2}`);
  return {
    prompt: `Mark where the lines $y = ${line(m1, b1)}$ and $y = ${line(m2, b2)}$ meet, and where each one crosses the $x$-axis.`,
    points: [[px, py], [x1, 0], [x2, 0]],
    labels: ["where they meet", `$y = ${line(m1, b1)}$ crosses`, `$y = ${line(m2, b2)}$ crosses`],
    curve: `${m1}*x+(${b1}); ${m2}*x+(${b2})`,
    explanation: `They meet where $${line(m1, b1)} = ${line(m2, b2)}$, so $x = ${px}$ and $y = ${py}$. Each crosses the $x$-axis where $y = 0$: $x = ${fr(x1)}$ and $x = ${fr(x2)}$.`,
  };
}

const NAMES = ["methane", "ethane", "propane", "butane", "pentane", "hexane"];
const n = rng.int(1, 6);
const f = `C${n === 1 ? "" : n}H${2 * n + 2}`;
return {
  prompt: `Balance the complete combustion of **${NAMES[n - 1]}**.`,
  reactants: [f, "O2"],
  products: ["CO2", "H2O"],
  explanation: `Carbon first: ${n === 1 ? "$1$ carbon makes $1\\,\\mathrm{CO_2}$" : `$${n}$ carbons make $${n}\\,\\mathrm{CO_2}$`}. Then hydrogen: $${2 * n + 2}$ hydrogens make $${n + 1}\\,\\mathrm{H_2O}$. That's $${2 * n} + ${n + 1} = ${3 * n + 1}$ oxygen atoms on the right, so ` +
    ((3 * n + 1) % 2
      ? `$\\frac{${3 * n + 1}}{2}\\,\\mathrm{O_2}$. Half a molecule isn't allowed, so double everything: $2\\,\\mathrm{${f.replace(/(\d+)/g, "_{$1}")}} + ${3 * n + 1}\\,\\mathrm{O_2} \\to ${2 * n}\\,\\mathrm{CO_2} + ${2 * n + 2}\\,\\mathrm{H_2O}$.`
      : `$${(3 * n + 1) / 2}\\,\\mathrm{O_2}$.`),
};
